def module_path() -> Path:
    """Return the target Medical History module path."""
    return Path(__file__).resolve().parent / "apps" / "patient_management" / MODULE_NAME


def parse_source(
    relative_path: str,
    source: str,
) -> ast.Module:
    """Parse one generated Python source file."""
    try:
        return ast.parse(
            source,
            filename=relative_path,
        )
    except SyntaxError as exc:
        raise RuntimeError(f"Invalid Python source: {relative_path}: {exc}") from exc


def has_all_declaration(tree: ast.Module) -> bool:
    """Return whether the module explicitly declares __all__."""
    return any(
        isinstance(node, ast.Assign)
        and any(
            isinstance(target, ast.Name) and target.id == "__all__"
            for target in node.targets
        )
        for node in tree.body
    )


def validate_source_contract() -> None:
    """Validate every Python file against the project source contract."""
    for relative_path, source in FILES.items():
        if not relative_path.endswith(".py"):
            continue

        tree = parse_source(
            relative_path=relative_path,
            source=source,
        )

        if not ast.get_docstring(tree, clean=False):
            raise RuntimeError(f"Module docstring missing: {relative_path}")

        if not any(
            isinstance(node, ast.ImportFrom)
            and node.module == "__future__"
            and any(alias.name == "annotations" for alias in node.names)
            for node in tree.body
        ):
            raise RuntimeError(
                f"from __future__ import annotations missing: {relative_path}"
            )

        if not has_all_declaration(tree):
            raise RuntimeError(f"__all__ missing: {relative_path}")

        for node in ast.walk(tree):
            if isinstance(
                node,
                (
                    ast.ClassDef,
                    ast.FunctionDef,
                    ast.AsyncFunctionDef,
                ),
            ) and not ast.get_docstring(node, clean=False):
                raise RuntimeError(
                    f"Definition docstring missing: {relative_path}:{node.name}"
                )

    print(f"STYLE: PASS ({len([p for p in FILES if p.endswith('.py')])} Python files)")


def workflow_registry_names() -> set[str]:
    """Extract registered workflow names from the registry."""
    tree = parse_source(
        relative_path="workflow_registry.py",
        source=FILES["workflow_registry.py"],
    )

    names: set[str] = set()

    for node in ast.walk(tree):
        if not isinstance(node, ast.Dict):
            continue

        for key in node.keys:
            if isinstance(key, ast.Constant) and isinstance(
                key.value,
                str,
            ):
                names.add(key.value)

    return names


def validate_architecture() -> None:
    """Validate the canonical Medical History architecture."""
    registered = workflow_registry_names()

    missing = [workflow for workflow in WORKFLOWS if workflow not in registered]

    if missing:
        raise RuntimeError("Workflow registry incomplete:\n  " + "\n  ".join(missing))

    model_source = FILES["models/medical_history.py"]

    if EXPECTED_PATIENT_IMPORT not in model_source:
        raise RuntimeError(
            "Canonical Patient import missing from models/medical_history.py."
        )

    if "Patient" not in model_source:
        raise RuntimeError(
            "Canonical Patient relationship missing from models/medical_history.py."
        )

    if "events/medical_history_verified.py" not in FILES:
        raise RuntimeError("Dedicated verification event is missing.")

    print("ARCHITECTURE: PASS")


def validate_serializer_structure() -> None:
    """Validate serializers against the canonical Patient serializer structure."""
    serializer_paths = tuple(
        path
        for path in FILES
        if path.startswith("api/serializers/")
        and path.endswith(".py")
        and path != "api/serializers/__init__.py"
    )

    for relative_path in serializer_paths:
        source = FILES[relative_path]
        tree = parse_source(
            relative_path=relative_path,
            source=source,
        )

        if not tree.body or not isinstance(tree.body[0], ast.Expr):
            raise RuntimeError(f"Serializer module docstring missing: {relative_path}")

        future_index = next(
            (
                index
                for index, node in enumerate(tree.body)
                if isinstance(node, ast.ImportFrom)
                and node.module == "__future__"
                and any(alias.name == "annotations" for alias in node.names)
            ),
            None,
        )

        if future_index != 1:
            raise RuntimeError(
                "Serializer structure requires module docstring followed by "
                f"future annotations import: {relative_path}"
            )

        serializer_classes = [
            node
            for node in tree.body
            if isinstance(node, ast.ClassDef) and node.name.endswith("Serializer")
        ]

        if len(serializer_classes) != 1:
            raise RuntimeError(
                "Serializer module must contain exactly one serializer class: "
                f"{relative_path}"
            )

        serializer_class = serializer_classes[0]

        if not ast.get_docstring(
            serializer_class,
            clean=False,
        ):
            raise RuntimeError(f"Serializer class docstring missing: {relative_path}")

        meta_classes = [
            node
            for node in serializer_class.body
            if isinstance(node, ast.ClassDef) and node.name == "Meta"
        ]

        if len(meta_classes) != 1:
            raise RuntimeError(f"Serializer Meta class missing: {relative_path}")

        meta_class = meta_classes[0]

        if not ast.get_docstring(
            meta_class,
            clean=False,
        ):
            raise RuntimeError(f"Serializer Meta docstring missing: {relative_path}")

        all_assignments = [
            node
            for node in tree.body
            if isinstance(node, ast.Assign)
            and any(
                isinstance(target, ast.Name) and target.id == "__all__"
                for target in node.targets
            )
        ]

        if len(all_assignments) != 1:
            raise RuntimeError(
                f"Serializer __all__ declaration missing: {relative_path}"
            )

        all_index = tree.body.index(all_assignments[0])

        if all_index != len(tree.body) - 1:
            raise RuntimeError(
                f"Serializer __all__ must be the final declaration: {relative_path}"
            )

    print(f"SERIALIZER STRUCTURE: PASS ({len(serializer_paths)} serializers)")


def validate_compile() -> None:
    """Compile all generated Python source before installation."""
    count = 0

    for relative_path, source in FILES.items():
        if not relative_path.endswith(".py"):
            continue

        compile(
            source,
            relative_path,
            "exec",
        )
        count += 1

    print(f"PY_COMPILE: PASS ({count} files)")


def write_files(target: Path) -> None:
    """Write the validated manifest to the target directory."""
    target.mkdir(
        parents=True,
        exist_ok=True,
    )

    for relative_path, source in FILES.items():
        destination = target / relative_path
        destination.parent.mkdir(
            parents=True,
            exist_ok=True,
        )
        destination.write_text(
            source.replace("\r\n", "\n").replace("\r", "\n").rstrip() + "\n",
            encoding="utf-8",
            newline="\n",
        )


def verify_files(target: Path) -> None:
    """Verify every generated file against the manifest."""
    for relative_path, expected_source in FILES.items():
        destination = target / relative_path

        if not destination.exists():
            raise RuntimeError(f"Generated file missing: {relative_path}")

        actual = (
            destination.read_text(
                encoding="utf-8",
            )
            .replace("\r\n", "\n")
            .replace("\r", "\n")
        )

        expected = (
            expected_source.replace("\r\n", "\n").replace("\r", "\n").rstrip() + "\n"
        )

        if actual != expected:
            raise RuntimeError(
                f"Generated source differs from manifest: {relative_path}"
            )

    print("VERIFY: PASS")


def main() -> int:
    """Run the Medical History installation pipeline."""
    print(f"DatavionOS Medical History Production Installer v{INSTALLER_VERSION}")
    print(f"Target: {module_path()}")

    try:
        validate_architecture()
        validate_source_contract()
        validate_serializer_structure()
        validate_compile()
        write_files(module_path())
        verify_files(module_path())
    except Exception as exc:
        print(f"INSTALLATION FAILED: {exc}")
        return 1

    print("INSTALLATION COMPLETE")
    print(
        "Workflow chain: "
        "API -> RBAC -> Workflow -> Policy -> Service -> "
        "Model -> Domain Event"
    )
    print("Canonical Patient: apps.patient_management.patients.models.Patient")
    print("No backup generated.")
    print("No migration generated.")

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
